import { useCallback, useEffect, useRef, useState } from "react";
import {
  ChevronRight,
  Copy,
  Download,
  ExternalLink,
  FileEdit,
  FolderPlus,
  HardDrive,
  KeyRound,
  Pencil,
  Plus,
  Server,
  Square,
  Terminal as TerminalIcon,
  Trash2,
  Upload,
  X,
} from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  CancelSFTPTransfer,
  CloseSFTP,
  CloseSSHShell,
  ConnectSSH,
  DeleteHost,
  DisconnectSSH,
  GenerateSSHKey,
  ImportSSHKey,
  InspectSSHKeys,
  ListHosts,
  ListLocalDir,
  OpenSFTP,
  OpenSSHShell,
  ReadSSHPublicKey,
  RevealLocalPath,
  ResizeSSHShell,
  SFTPDownloadAsync,
  SFTPList,
  SFTPMkdir,
  SFTPRemove,
  SFTPRename,
  SFTPReadFile,
  SFTPUploadAsync,
  SFTPWriteFile,
  SaveHost,
  StartRemoteEdit,
  StopRemoteEdit,
  WriteSSHShell,
} from "../../wailsjs/go/controllers/SSH";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  EventsOn,
  OpenDirectoryDialog,
  OpenFileDialog,
  SaveFileDialog,
} from "../../wailsjs/runtime";
import DocumentEditor from "../components/documents/DocumentEditor";
import RemoteTerminal from "../components/terminal/RemoteTerminal";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

type Host = {
  name: string;
  address: string;
  port: number;
  user: string;
  authMode: string;
  keyName?: string;
  tags?: string[];
  jumpHosts?: string[];
  proxyCommand?: string;
  lastUsed?: string;
};

type KeyInfo = { name: string; algorithm: string; fingerprint: string };
type Entry = { name: string; isDir: boolean; size: number };
type LocalEntry = { name: string; isDir: boolean; size: number };

type Session =
  | { host: string; kind: "shell"; shellId: string }
  | { host: string; kind: "files"; sftpId: string; connId: string };

type Transfer = {
  id: string;
  label: string;
  bytes: number;
  total: number;
  done: boolean;
  error?: string;
};

type RemoteEditSession = {
  id: string;
  remotePath: string;
  localPath: string;
};

// The SSH page: saved hosts (with jump/proxy settings), generated and
// imported keys, a remote shell, and a dual-pane SFTP browser with
// cancellable transfers plus remote file editing.
export default function Ssh() {
  const t = useT();
  const dialogs = useDialogs();
  const [tab, setTab] = useState<"hosts" | "keys">("hosts");
  const [hosts, setHosts] = useState<Host[]>([]);
  const [editing, setEditing] = useState<Host | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [session, setSession] = useState<Session | null>(null);
  const [stages, setStages] = useState<{ stage: string; detail?: string }[]>([]);

  const refresh = useCallback(() => {
    ListHosts()
      .then((list: Host[]) =>
        setHosts(
          // Recently used hosts first; never-used hosts keep name order.
          [...(list ?? [])].sort((a, b) =>
            (b.lastUsed ?? "").localeCompare(a.lastUsed ?? "") || a.name.localeCompare(b.name)
          )
        )
      )
      .catch(() => {
        /* pre-startup */
      });
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Live connect-stage timeline while a host is being reached.
  useEffect(() => {
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("ssh:connect-stage", (p: { host: string; stage: string; detail?: string }) => {
      setStages((prev) => [...prev.slice(-8), { stage: p.stage, detail: p.detail }]);
    });
  }, []);

  const closeSession = () => {
    if (!session) return;
    if (session.kind === "shell") CloseSSHShell(session.shellId).catch(() => {});
    else {
      CloseSFTP(session.sftpId).catch(() => {});
      DisconnectSSH(session.connId).catch(() => {});
    }
    setSession(null);
  };

  const openShell = async (host: Host) => {
    setStages([]);
    try {
      const shellId = await OpenSSHShell(host.name, 80, 24);
      setSession({ host: host.name, kind: "shell", shellId });
      refresh();
    } catch (error) {
      await dialogs.alert({ title: host.name, message: String(error) });
    }
  };

  const openFiles = async (host: Host) => {
    setStages([]);
    try {
      const connId = await ConnectSSH(host.name);
      const sftpId = await OpenSFTP(connId);
      setSession({ host: host.name, kind: "files", sftpId, connId });
      refresh();
    } catch (error) {
      await dialogs.alert({ title: host.name, message: String(error) });
    }
  };

  const remove = async (host: Host) => {
    const yes = await dialogs.confirm({
      title: t("ssh.deleteConfirm", { name: host.name }),
      danger: true,
    });
    if (!yes) return;
    await DeleteHost(host.name);
    refresh();
  };

  return (
    <div className="flex h-full min-h-0 flex-col">
      <header className="flex items-center justify-between">
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => setTab("hosts")}
            className={`rounded-md px-3 py-1.5 text-xs font-medium ${
              tab === "hosts" ? "bg-white/10 text-white" : "text-white/50 hover:text-white/80"
            }`}
          >
            {t("ssh.tabHosts")}
          </button>
          <button
            type="button"
            onClick={() => setTab("keys")}
            className={`rounded-md px-3 py-1.5 text-xs font-medium ${
              tab === "keys" ? "bg-white/10 text-white" : "text-white/50 hover:text-white/80"
            }`}
          >
            {t("ssh.tabKeys")}
          </button>
        </div>
        {tab === "hosts" && (
          <button
            type="button"
            onClick={() => {
              setEditing(null);
              setShowForm(true);
            }}
            className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85"
          >
            <Plus className="h-3.5 w-3.5" /> {t("ssh.newHost")}
          </button>
        )}
      </header>

      <div className="mt-3 min-h-0 flex-1 overflow-y-auto pr-0.5">
        {tab === "hosts" ? (
          <div className="space-y-3">
            {showForm && (
              <HostForm
                key={editing?.name ?? "new"}
                host={editing}
                hosts={hosts}
                onSave={async (host, password) => {
                  await SaveHost(host as any, password);
                  setShowForm(false);
                  setEditing(null);
                  refresh();
                }}
                onCancel={() => {
                  setShowForm(false);
                  setEditing(null);
                }}
              />
            )}
            {hosts.length === 0 && !showForm && (
              <section className="glass p-8 text-center">
                <p className="text-sm text-white/50">{t("ssh.empty")}</p>
              </section>
            )}
            {hosts.map((host) => (
              <article key={host.name} className="glass flex items-center gap-3 p-3">
                <Server className="h-4 w-4 shrink-0 text-accent2" />
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-1.5">
                    <span className="truncate text-sm font-medium text-white/90">{host.name}</span>
                    <span className="rounded-full border border-white/15 px-1.5 py-0.5 text-[9px] uppercase tracking-wide text-white/40">
                      {host.authMode}
                    </span>
                    {(host.tags ?? []).map((tag) => (
                      <span
                        key={tag}
                        className="rounded-full border border-accent2/30 px-1.5 py-0.5 text-[9px] text-accent2"
                      >
                        {tag}
                      </span>
                    ))}
                    {(host.jumpHosts?.length ?? 0) > 0 && (
                      <span
                        title={host.jumpHosts!.join(" → ")}
                        className="rounded-full border border-amber-400/30 px-1.5 py-0.5 text-[9px] text-amber-300"
                      >
                        ⇄ {host.jumpHosts!.length}
                      </span>
                    )}
                    {host.proxyCommand && (
                      <span
                        title={host.proxyCommand}
                        className="rounded-full border border-amber-400/30 px-1.5 py-0.5 text-[9px] text-amber-300"
                      >
                        proxy
                      </span>
                    )}
                  </div>
                  <p className="truncate font-mono text-[11px] text-white/40">
                    {host.user}@{host.address}:{host.port}
                    {host.keyName ? ` · ${host.keyName}` : ""}
                  </p>
                  {host.lastUsed && (
                    <p className="text-[10px] text-white/30">
                      {t("ssh.lastUsed")}: {new Date(host.lastUsed).toLocaleString()}
                    </p>
                  )}
                </div>
                <div className="flex shrink-0 items-center gap-1">
                  <button
                    type="button"
                    onClick={() => void openShell(host)}
                    title={t("ssh.openShell")}
                    className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                  >
                    <TerminalIcon className="h-3 w-3" />
                  </button>
                  <button
                    type="button"
                    onClick={() => void openFiles(host)}
                    title={t("ssh.openFiles")}
                    className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                  >
                    <HardDrive className="h-3 w-3" />
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setEditing(host);
                      setShowForm(true);
                    }}
                    title={t("ssh.edit")}
                    className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                  >
                    <Pencil className="h-3 w-3" />
                  </button>
                  <button
                    type="button"
                    onClick={() => void remove(host)}
                    title={t("ssh.delete")}
                    className="rounded border border-red-400/30 bg-red-500/10 p-1.5 text-red-300 hover:bg-red-500/20"
                  >
                    <Trash2 className="h-3 w-3" />
                  </button>
                </div>
              </article>
            ))}

            {stages.length > 0 && (
              <section className="glass px-3 py-2">
                <p className="mb-1 text-[10px] uppercase tracking-wide text-white/40">
                  {t("ssh.connectTimeline")}
                </p>
                <div className="flex flex-wrap items-center gap-1">
                  {stages.map((s, i) => (
                    <span
                      key={i}
                      className="rounded-full border border-white/10 px-2 py-0.5 font-mono text-[10px] text-white/60"
                    >
                      {s.stage}
                      {s.detail ? ` · ${s.detail}` : ""}
                    </span>
                  ))}
                </div>
              </section>
            )}

            {session && (
              <section className="glass overflow-hidden">
                <div className="flex items-center justify-between border-b border-white/10 px-3 py-2">
                  <span className="font-mono text-[11px] text-white/60">
                    {session.kind === "shell"
                      ? t("ssh.shellTitle", { name: session.host })
                      : t("ssh.filesTitle", { name: session.host })}
                  </span>
                  <button
                    type="button"
                    onClick={closeSession}
                    className="rounded border border-white/10 p-1 text-white/60 hover:bg-white/10 hover:text-white"
                  >
                    <X className="h-3 w-3" />
                  </button>
                </div>
                {session.kind === "shell" ? (
                  <div className="h-72">
                    <RemoteTerminal shellId={session.shellId} />
                  </div>
                ) : (
                  <SftpBrowser sftpId={session.sftpId} />
                )}
              </section>
            )}
          </div>
        ) : (
          <KeysPanel />
        )}
      </div>
    </div>
  );
}

function HostForm({
  host,
  hosts,
  onSave,
  onCancel,
}: {
  host: Host | null;
  hosts: Host[];
  onSave: (host: Host, password: string) => void;
  onCancel: () => void;
}) {
  const t = useT();
  const [name, setName] = useState(host?.name ?? "");
  const [address, setAddress] = useState(host?.address ?? "");
  const [port, setPort] = useState(String(host?.port ?? 22));
  const [user, setUser] = useState(host?.user ?? "root");
  const [authMode, setAuthMode] = useState(host?.authMode ?? "password");
  const [password, setPassword] = useState("");
  const [keyName, setKeyName] = useState(host?.keyName ?? "");
  const [tags, setTags] = useState((host?.tags ?? []).join(", "));
  const [jumps, setJumps] = useState((host?.jumpHosts ?? []).join(", "));
  const [proxy, setProxy] = useState(host?.proxyCommand ?? "");
  const [keys, setKeys] = useState<string[]>([]);

  useEffect(() => {
    InspectSSHKeys()
      .then((list: KeyInfo[]) => setKeys((list ?? []).map((k) => k.name)))
      .catch(() => {});
  }, []);

  const otherHosts = hosts.filter((h) => h.name !== host?.name).map((h) => h.name);
  const valid =
    name.trim() !== "" &&
    address.trim() !== "" &&
    user.trim() !== "" &&
    Number(port) > 0 &&
    (authMode === "password" || keyName !== "") &&
    jumps
      .split(",")
      .map((j) => j.trim())
      .filter(Boolean)
      .every((j) => otherHosts.includes(j));

  return (
    <section className="glass space-y-3 p-4">
      <div className="grid grid-cols-4 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("ssh.hostName")}</span>
          <input className="input w-full" value={name} onChange={(e) => setName(e.target.value)} />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("ssh.address")}</span>
          <input
            className="input w-full font-mono"
            placeholder="203.0.113.10"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("ssh.port")}</span>
          <input
            className="input w-full font-mono"
            value={port}
            onChange={(e) => setPort(e.target.value)}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("ssh.user")}</span>
          <input
            className="input w-full font-mono"
            value={user}
            onChange={(e) => setUser(e.target.value)}
          />
        </label>
      </div>
      <div className="grid grid-cols-3 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("ssh.authMode")}</span>
          <select
            className="input w-full"
            value={authMode}
            onChange={(e) => setAuthMode(e.target.value)}
          >
            <option value="password">{t("ssh.authPassword")}</option>
            <option value="key">{t("ssh.authKey")}</option>
          </select>
        </label>
        {authMode === "password" ? (
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("ssh.password")}</span>
            <input
              type="password"
              className="input w-full font-mono"
              placeholder={host ? t("ssh.passwordKeep") : ""}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </label>
        ) : (
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("ssh.key")}</span>
            <select
              className="input w-full"
              value={keyName}
              onChange={(e) => setKeyName(e.target.value)}
            >
              <option value="">—</option>
              {keys.map((k) => (
                <option key={k} value={k}>
                  {k}
                </option>
              ))}
            </select>
          </label>
        )}
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("ssh.tags")}</span>
          <input
            className="input w-full"
            placeholder="production, vps-a"
            value={tags}
            onChange={(e) => setTags(e.target.value)}
          />
        </label>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">
            {t("ssh.jumpHosts")}{" "}
            <span className="text-white/30">({otherHosts.join(", ") || "—"})</span>
          </span>
          <input
            className="input w-full font-mono"
            placeholder="bastion1, bastion2"
            value={jumps}
            onChange={(e) => setJumps(e.target.value)}
          />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("ssh.proxyCommand")}</span>
          <input
            className="input w-full font-mono"
            placeholder="ssh -W %h:%p corp-gw"
            value={proxy}
            onChange={(e) => setProxy(e.target.value)}
          />
        </label>
      </div>
      <div className="flex justify-end gap-2 pt-2">
        <button
          type="button"
          onClick={onCancel}
          className="rounded-md border border-white/10 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10"
        >
          {t("dialog.cancel")}
        </button>
        <button
          type="button"
          disabled={!valid}
          onClick={() =>
            onSave(
              {
                name,
                address,
                port: Number(port) || 22,
                user,
                authMode,
                keyName: authMode === "key" ? keyName : "",
                tags: tags
                  .split(",")
                  .map((s) => s.trim())
                  .filter(Boolean),
                jumpHosts: jumps
                  .split(",")
                  .map((s) => s.trim())
                  .filter(Boolean),
                proxyCommand: proxy.trim(),
              },
              authMode === "password" ? password : ""
            )
          }
          className="rounded-md bg-accent px-4 py-1.5 text-xs font-medium text-white disabled:opacity-40"
        >
          {t("dialog.save")}
        </button>
      </div>
    </section>
  );
}

// RemoteTerminal lives in components/terminal and is shared with the
// terminal workspace's SSH panes; the page embeds it at a fixed height.

// SftpBrowser is a dual-pane file view: local on the left, remote on the
// right, with cancellable transfers in between and remote file editing.
function SftpBrowser({ sftpId }: { sftpId: string }) {
  const t = useT();
  const dialogs = useDialogs();
  const [remotePath, setRemotePath] = useState("/");
  const [remoteEntries, setRemoteEntries] = useState<Entry[]>([]);
  const [localPath, setLocalPath] = useState("");
  const [localEntries, setLocalEntries] = useState<LocalEntry[]>([]);
  const [busy, setBusy] = useState(false);
  const [transfers, setTransfers] = useState<Transfer[]>([]);
  const [editor, setEditor] = useState<{ path: string; content: string; dirty: boolean } | null>(
    null
  );
  const [editSession, setEditSession] = useState<RemoteEditSession | null>(null);

  const join = (dir: string, name: string) => (dir === "/" ? "/" + name : dir + "/" + name);

  const loadRemote = useCallback(
    (dir: string) => {
      setBusy(true);
      SFTPList(sftpId, dir)
        .then((list: Entry[]) => {
          setRemoteEntries(list ?? []);
          setRemotePath(dir);
        })
        .catch((error) => dialogs.alert({ title: dir, message: String(error) }))
        .finally(() => setBusy(false));
    },
    [sftpId, dialogs]
  );

  const loadLocal = useCallback(
    (dir: string) => {
      ListLocalDir(dir || "")
        .then((list: LocalEntry[]) => {
          setLocalEntries(list ?? []);
          if (dir) setLocalPath(dir);
        })
        .catch((error) => dialogs.alert({ title: dir || "~", message: String(error) }));
    },
    [dialogs]
  );

  useEffect(() => {
    // Deferred so no setState runs synchronously inside the effect body.
    const timer = setTimeout(() => {
      loadRemote("/");
      loadLocal("");
    }, 0);
    return () => clearTimeout(timer);
  }, [loadRemote, loadLocal]);

  // Transfer subscriptions are per transfer ID — see subscribeTransfer,
  // invoked the moment a transfer starts.

  const subscribeTransfer = (transferID: string) => {
    // @ts-ignore EventsOn returns a cancel function
    const c1 = EventsOn(`sftp:progress:${transferID}`, (p: { bytes: number; total: number }) => {
      setTransfers((prev) =>
        prev.map((tr) =>
          tr.id === transferID ? { ...tr, bytes: p.bytes, total: p.total } : tr
        )
      );
    });
    // @ts-ignore EventsOn returns a cancel function
    const c2 = EventsOn(`sftp:done:${transferID}`, (p: { error: string }) => {
      setTransfers((prev) =>
        prev.map((tr) =>
          tr.id === transferID ? { ...tr, done: true, error: p.error || undefined } : tr
        )
      );
      c1?.();
      c2?.();
    });
  };

  const startUpload = async (entry: LocalEntry) => {
    if (entry.isDir) return;
    try {
      const transferID = await SFTPUploadAsync(
        sftpId,
        join(localPath, entry.name).replace(/\//g, "\\"),
        join(remotePath, entry.name)
      );
      setTransfers((prev) => [
        ...prev,
        { id: transferID, label: `↑ ${entry.name}`, bytes: 0, total: entry.size, done: false },
      ]);
      subscribeTransfer(transferID);
    } catch (error) {
      await dialogs.alert({ title: entry.name, message: String(error) });
    }
  };

  const startDownload = async (entry: Entry) => {
    if (entry.isDir) return;
    const local = await SaveFileDialog({
      Title: t("ssh.saveAs"),
      DefaultFilename: entry.name,
    });
    if (!local) return;
    try {
      const transferID = await SFTPDownloadAsync(sftpId, join(remotePath, entry.name), local);
      setTransfers((prev) => [
        ...prev,
        { id: transferID, label: `↓ ${entry.name}`, bytes: 0, total: entry.size, done: false },
      ]);
      subscribeTransfer(transferID);
    } catch (error) {
      await dialogs.alert({ title: entry.name, message: String(error) });
    }
  };

  const pickLocalDir = async () => {
    const dir = await OpenDirectoryDialog({ Title: t("ssh.pickLocalDir") });
    if (dir) loadLocal(dir);
  };

  const mkdir = async () => {
    const name = window.prompt(t("ssh.newFolderName"));
    if (!name) return;
    await SFTPMkdir(sftpId, join(remotePath, name));
    loadRemote(remotePath);
  };

  const rename = async (entry: Entry) => {
    const next = window.prompt(t("ssh.renameTo"), entry.name);
    if (!next || next === entry.name) return;
    await SFTPRename(sftpId, join(remotePath, entry.name), join(remotePath, next));
    loadRemote(remotePath);
  };

  const remove = async (entry: Entry) => {
    const yes = await dialogs.confirm({
      title: t("ssh.removeConfirm", { name: entry.name }),
      danger: true,
    });
    if (!yes) return;
    await SFTPRemove(sftpId, join(remotePath, entry.name));
    loadRemote(remotePath);
  };

  const openEditor = async (entry: Entry) => {
    try {
      const content = await SFTPReadFile(sftpId, join(remotePath, entry.name));
      setEditor({ path: join(remotePath, entry.name), content, dirty: false });
    } catch (error) {
      await dialogs.alert({ title: entry.name, message: String(error) });
    }
  };

  const saveEditor = async () => {
    if (!editor) return;
    await SFTPWriteFile(sftpId, editor.path, editor.content);
    setEditor((e) => (e ? { ...e, dirty: false } : e));
  };

  const startExternalEdit = async (entry: Entry) => {
    try {
      const view = await StartRemoteEdit(sftpId, join(remotePath, entry.name));
      setEditSession({ id: view.id, remotePath: view.remotePath, localPath: view.localPath });
      await RevealLocalPath(view.localPath);
    } catch (error) {
      await dialogs.alert({ title: entry.name, message: String(error) });
    }
  };

  const stopExternalEdit = async () => {
    if (!editSession) return;
    await StopRemoteEdit(editSession.id, false);
    setEditSession(null);
  };

  const remoteParent = () => {
    if (remotePath === "/") return;
    loadRemote(remotePath.slice(0, remotePath.lastIndexOf("/")) || "/");
  };
  const localParent = () => {
    const sep = localPath.lastIndexOf("\\");
    const up = sep > 0 ? localPath.slice(0, sep) : localPath.slice(0, 2);
    loadLocal(up);
  };

  const sortedRemote = [...remoteEntries].sort((a, b) => {
    if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
  const sortedLocal = [...localEntries].sort((a, b) => {
    if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
    return a.name.localeCompare(b.name);
  });

  return (
    <div className="flex flex-col">
      <div className="grid grid-cols-2 divide-x divide-white/10">
        {/* Local pane */}
        <div className="min-w-0">
          <div className="flex items-center gap-1.5 border-b border-white/10 px-2 py-1.5">
            <button
              type="button"
              onClick={localParent}
              title={t("ssh.parentDir")}
              className="rounded border border-white/10 bg-white/5 p-1 text-white/60 hover:bg-white/10 hover:text-white"
            >
              <ChevronRight className="h-3 w-3 rotate-180" />
            </button>
            <button
              type="button"
              onClick={() => void pickLocalDir()}
              title={t("ssh.pickLocalDir")}
              className="rounded border border-white/10 bg-white/5 px-1.5 py-0.5 text-[10px] text-white/60 hover:bg-white/10 hover:text-white"
            >
              {t("ssh.chooseDir")}
            </button>
            <span className="min-w-0 flex-1 truncate font-mono text-[10px] text-white/40">
              {localPath || "~"}
            </span>
          </div>
          <div className="max-h-64 overflow-y-auto">
            {sortedLocal.map((entry) => (
              <div key={entry.name} className="group flex items-center gap-1.5 px-2 py-1 hover:bg-white/5">
                <button
                  type="button"
                  onClick={() => entry.isDir && loadLocal(join(localPath, entry.name))}
                  className={`min-w-0 flex-1 truncate text-left font-mono text-[10px] ${
                    entry.isDir ? "text-white/70 hover:text-accent2" : "text-white/50"
                  }`}
                >
                  {entry.isDir ? "▸ " : "  "}
                  {entry.name}
                </button>
                {!entry.isDir && (
                  <button
                    type="button"
                    onClick={() => void startUpload(entry)}
                    title={t("ssh.upload")}
                    className="rounded p-0.5 text-white/40 opacity-0 hover:bg-white/10 hover:text-white group-hover:opacity-100"
                  >
                    <Upload className="h-3 w-3" />
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Remote pane */}
        <div className="min-w-0">
          <div className="flex items-center gap-1.5 border-b border-white/10 px-2 py-1.5">
            <button
              type="button"
              onClick={remoteParent}
              title={t("ssh.parentDir")}
              className="rounded border border-white/10 bg-white/5 p-1 text-white/60 hover:bg-white/10 hover:text-white"
            >
              <ChevronRight className="h-3 w-3 rotate-180" />
            </button>
            <button
              type="button"
              onClick={() => void mkdir()}
              title={t("ssh.newFolder")}
              className="rounded border border-white/10 bg-white/5 p-1 text-white/60 hover:bg-white/10 hover:text-white"
            >
              <FolderPlus className="h-3 w-3" />
            </button>
            <input
              className="min-w-0 flex-1 rounded bg-black/30 px-1.5 py-0.5 font-mono text-[10px] text-white/70 outline-none focus:ring-1 focus:ring-accent/50"
              value={remotePath}
              onChange={(e) => setRemotePath(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") loadRemote((e.target as HTMLInputElement).value);
              }}
            />
          </div>
          <div className="max-h-64 overflow-y-auto">
            {busy && <p className="px-2 py-1 text-[10px] text-white/40">{t("ssh.loading")}</p>}
            {sortedRemote.map((entry) => (
              <div key={entry.name} className="group flex items-center gap-1.5 px-2 py-1 hover:bg-white/5">
                <button
                  type="button"
                  onClick={() => entry.isDir && loadRemote(join(remotePath, entry.name))}
                  className={`min-w-0 flex-1 truncate text-left font-mono text-[10px] ${
                    entry.isDir ? "text-white/70 hover:text-accent2" : "text-white/50"
                  }`}
                >
                  {entry.isDir ? "▸ " : "  "}
                  {entry.name}
                </button>
                <span className="shrink-0 font-mono text-[9px] text-white/25">
                  {entry.isDir ? "—" : fmtSize(entry.size)}
                </span>
                <div className="flex shrink-0 gap-0.5 opacity-0 transition-opacity group-hover:opacity-100">
                  {!entry.isDir && (
                    <>
                      <button
                        type="button"
                        onClick={() => void openEditor(entry)}
                        title={t("ssh.editFile")}
                        className="rounded p-0.5 text-white/40 hover:bg-white/10 hover:text-white"
                      >
                        <FileEdit className="h-3 w-3" />
                      </button>
                      <button
                        type="button"
                        onClick={() => void startExternalEdit(entry)}
                        title={t("ssh.editExternal")}
                        className="rounded p-0.5 text-white/40 hover:bg-white/10 hover:text-white"
                      >
                        <ExternalLink className="h-3 w-3" />
                      </button>
                      <button
                        type="button"
                        onClick={() => void startDownload(entry)}
                        title={t("ssh.download")}
                        className="rounded p-0.5 text-white/40 hover:bg-white/10 hover:text-white"
                      >
                        <Download className="h-3 w-3" />
                      </button>
                    </>
                  )}
                  <button
                    type="button"
                    onClick={() => void rename(entry)}
                    title={t("ssh.rename")}
                    className="rounded p-0.5 text-white/40 hover:bg-white/10 hover:text-white"
                  >
                    <Pencil className="h-3 w-3" />
                  </button>
                  <button
                    type="button"
                    onClick={() => void remove(entry)}
                    title={t("ssh.delete")}
                    className="rounded p-0.5 text-red-300/60 hover:bg-red-500/20 hover:text-red-300"
                  >
                    <Trash2 className="h-3 w-3" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Active transfers */}
      {transfers.length > 0 && (
        <div className="space-y-1 border-t border-white/10 px-2 py-1.5">
          {transfers.map((tr) => (
            <div key={tr.id} className="flex items-center gap-2">
              <span className="w-40 shrink-0 truncate font-mono text-[10px] text-white/60">
                {tr.label}
              </span>
              <div className="h-1.5 flex-1 overflow-hidden rounded bg-white/10">
                <div
                  className={`h-full ${tr.error ? "bg-red-400" : tr.done ? "bg-emerald-400" : "bg-accent2"}`}
                  style={{
                    width: tr.total > 0 ? `${Math.min(100, (tr.bytes / tr.total) * 100)}%` : "0%",
                  }}
                />
              </div>
              <span className="w-24 shrink-0 text-right font-mono text-[9px] text-white/40">
                {tr.error
                  ? t("ssh.transferError")
                  : tr.done
                    ? t("ssh.transferDone")
                    : `${fmtSize(tr.bytes)} / ${fmtSize(tr.total)}`}
              </span>
              {!tr.done && !tr.error && (
                <button
                  type="button"
                  onClick={() => void CancelSFTPTransfer(tr.id)}
                  title={t("ssh.cancel")}
                  className="rounded p-0.5 text-white/40 hover:bg-red-500/20 hover:text-red-300"
                >
                  <Square className="h-3 w-3" />
                </button>
              )}
              {tr.done && (
                <button
                  type="button"
                  onClick={() =>
                    setTransfers((prev) => prev.filter((x) => x.id !== tr.id))
                  }
                  className="rounded p-0.5 text-white/30 hover:bg-white/10 hover:text-white"
                >
                  <X className="h-3 w-3" />
                </button>
              )}
            </div>
          ))}
        </div>
      )}

      {/* External edit session banner */}
      {editSession && (
        <div className="flex items-center gap-2 border-t border-white/10 bg-amber-500/5 px-2 py-1.5">
          <ExternalLink className="h-3 w-3 shrink-0 text-amber-300" />
          <span className="min-w-0 flex-1 truncate font-mono text-[10px] text-amber-200/80">
            {t("ssh.externalEditActive")}: {editSession.remotePath} → {editSession.localPath}
          </span>
          <button
            type="button"
            onClick={() => void RevealLocalPath(editSession.localPath)}
            className="rounded border border-white/10 px-1.5 py-0.5 text-[10px] text-white/60 hover:bg-white/10 hover:text-white"
          >
            {t("ssh.reveal")}
          </button>
          <button
            type="button"
            onClick={() => void stopExternalEdit()}
            className="rounded border border-red-400/30 bg-red-500/10 px-1.5 py-0.5 text-[10px] text-red-300 hover:bg-red-500/20"
          >
            {t("ssh.stopWatching")}
          </button>
        </div>
      )}

      {/* Internal editor */}
      {editor && (
        <div className="border-t border-white/10">
          <div className="flex items-center justify-between px-2 py-1.5">
            <span className="min-w-0 flex-1 truncate font-mono text-[10px] text-white/60">
              {editor.path}
              {editor.dirty ? " •" : ""}
            </span>
            <div className="flex shrink-0 gap-1.5">
              <button
                type="button"
                onClick={() => void saveEditor()}
                disabled={!editor.dirty}
                className="rounded bg-accent px-2 py-0.5 text-[10px] font-medium text-white disabled:opacity-40"
              >
                {t("ssh.saveRemote")}
              </button>
              <button
                type="button"
                onClick={() => setEditor(null)}
                className="rounded border border-white/10 px-2 py-0.5 text-[10px] text-white/60 hover:bg-white/10"
              >
                {t("dialog.close")}
              </button>
            </div>
          </div>
          <div className="h-64">
            <DocumentEditor
              value={editor.content}
              language={fileLanguageOf(editor.path)}
              onChange={(v) => setEditor((e) => (e ? { ...e, content: v, dirty: true } : e))}
              onSave={saveEditor}
            />
          </div>
        </div>
      )}
    </div>
  );
}

function fileLanguageOf(path: string): string {
  const ext = path.split(".").pop()?.toLowerCase() ?? "";
  const map: Record<string, string> = {
    json: "json",
    yaml: "yaml",
    yml: "yaml",
    conf: "ini",
    ini: "ini",
    env: "ini",
    sh: "shell",
    js: "javascript",
    ts: "typescript",
    php: "php",
    py: "python",
    md: "markdown",
    sql: "sql",
  };
  return map[ext] ?? "plaintext";
}

function fmtSize(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  return `${(n / 1024 / 1024 / 1024).toFixed(1)} GB`;
}

// KeysPanel generates, imports and inspects SSH keys.
function KeysPanel() {
  const t = useT();
  const dialogs = useDialogs();
  const [keys, setKeys] = useState<KeyInfo[]>([]);
  const [name, setName] = useState("");
  const [type, setType] = useState("ed25519");
  const [bits, setBits] = useState("4096");
  const [pub, setPub] = useState("");
  const [busy, setBusy] = useState(false);
  const [importName, setImportName] = useState("");
  const [importPem, setImportPem] = useState("");

  const refresh = useCallback(() => {
    InspectSSHKeys()
      .then((list: KeyInfo[]) => setKeys(list ?? []))
      .catch(() => {});
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const generate = async () => {
    setBusy(true);
    try {
      const publicKey = await GenerateSSHKey(name.trim(), type, Number(bits) || 0);
      setName("");
      refresh();
      setPub(publicKey);
    } catch (error) {
      await dialogs.alert({ title: t("ssh.tabKeys"), message: String(error) });
    } finally {
      setBusy(false);
    }
  };

  const importKey = async () => {
    setBusy(true);
    try {
      const publicKey = await ImportSSHKey(importName.trim(), importPem);
      setImportName("");
      setImportPem("");
      refresh();
      setPub(publicKey);
    } catch (error) {
      await dialogs.alert({ title: t("ssh.importKey"), message: String(error) });
    } finally {
      setBusy(false);
    }
  };

  const show = async (key: KeyInfo) => {
    try {
      setPub(await ReadSSHPublicKey(key.name));
    } catch (error) {
      await dialogs.alert({ title: key.name, message: String(error) });
    }
  };

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(pub);
    } catch {
      /* clipboard unavailable */
    }
  };

  return (
    <div className="space-y-3">
      <section className="glass space-y-3 p-4">
        <div className="grid grid-cols-3 gap-3">
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("ssh.keyName")}</span>
            <input
              className="input w-full font-mono"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </label>
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("ssh.keyType")}</span>
            <select
              className="input w-full"
              value={type}
              onChange={(e) => setType(e.target.value)}
            >
              <option value="ed25519">ed25519</option>
              <option value="rsa">rsa</option>
              <option value="ecdsa">ecdsa</option>
            </select>
          </label>
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("ssh.keyBits")}</span>
            <input
              className="input w-full font-mono disabled:opacity-40"
              disabled={type !== "rsa"}
              value={type === "rsa" ? bits : "—"}
              onChange={(e) => setBits(e.target.value)}
            />
          </label>
        </div>
        <div className="flex justify-end">
          <button
            type="button"
            disabled={!name.trim() || busy}
            onClick={() => void generate()}
            className="flex items-center gap-1.5 rounded-md bg-accent px-4 py-1.5 text-xs font-medium text-white disabled:opacity-40"
          >
            <KeyRound className="h-3.5 w-3.5" /> {t("ssh.generateKey")}
          </button>
        </div>
      </section>

      <section className="glass space-y-3 p-4">
        <p className="text-[11px] uppercase tracking-wide text-white/40">{t("ssh.importKey")}</p>
        <div className="grid grid-cols-3 gap-3">
          <label className="space-y-1 text-xs">
            <span className="text-white/60">{t("ssh.keyName")}</span>
            <input
              className="input w-full font-mono"
              value={importName}
              onChange={(e) => setImportName(e.target.value)}
            />
          </label>
          <div className="col-span-2 space-y-1 text-xs">
            <span className="text-white/60">{t("ssh.privateKeyPem")}</span>
            <textarea
              className="input h-10 w-full resize-y font-mono text-[10px]"
              placeholder={"-----BEGIN OPENSSH PRIVATE KEY-----\n…"}
              value={importPem}
              onChange={(e) => setImportPem(e.target.value)}
            />
          </div>
        </div>
        <div className="flex justify-end">
          <button
            type="button"
            disabled={!importName.trim() || !importPem.includes("PRIVATE KEY") || busy}
            onClick={() => void importKey()}
            className="rounded-md border border-accent/50 bg-accent/15 px-4 py-1.5 text-xs font-medium text-white disabled:opacity-40"
          >
            {t("ssh.importKey")}
          </button>
        </div>
      </section>

      {keys.length > 0 && (
        <section className="glass divide-y divide-white/5">
          {keys.map((key) => (
            <button
              key={key.name}
              type="button"
              onClick={() => void show(key)}
              className="flex w-full items-center gap-2 px-3 py-2 text-left hover:bg-white/5"
            >
              <KeyRound className="h-3.5 w-3.5 shrink-0 text-white/40" />
              <span className="shrink-0 font-mono text-xs text-white/80">{key.name}</span>
              <span className="shrink-0 rounded border border-white/10 px-1 text-[9px] text-white/40">
                {key.algorithm}
              </span>
              <span className="min-w-0 flex-1 truncate font-mono text-[10px] text-white/30">
                {key.fingerprint}
              </span>
            </button>
          ))}
        </section>
      )}

      {pub && (
        <section className="glass space-y-2 p-4">
          <div className="flex items-center justify-between">
            <span className="text-[11px] uppercase tracking-wide text-white/40">
              {t("ssh.publicKey")}
            </span>
            <button
              type="button"
              onClick={() => void copy()}
              className="flex items-center gap-1 rounded border border-white/10 px-2 py-1 text-[11px] text-white/60 hover:bg-white/10 hover:text-white"
            >
              <Copy className="h-3 w-3" /> {t("ssh.copy")}
            </button>
          </div>
          <pre className="max-h-24 overflow-auto rounded bg-black/40 p-2 font-mono text-[10px] leading-relaxed text-white/70">
            {pub}
          </pre>
        </section>
      )}
    </div>
  );
}
